package com.lmspilot.ai.platform;import com.fasterxml.jackson.databind.JsonNode;import java.util.*;import java.util.regex.Pattern;
public final class QuestionSetBusinessValidator{private static final Set<String>TYPES=Set.of("SINGLE_CHOICE","MULTIPLE_CHOICE","TRUE_FALSE"),DIFF=Set.of("EASY","MEDIUM","HARD");private static final Pattern OPTION=Pattern.compile("^[A-Z][A-Z0-9_]{0,15}$");private static final Set<String>ROOT=Set.of("schemaVersion","source","language","title","questions"),SOURCE=Set.of("courseId","documentVersionIds","provider","model","generatedAt"),QUESTION=Set.of("externalId","type","stem","difficulty","topic","learningObjective","points","options","correctOptionIds","explanation","citations","tags"),OPT=Set.of("id","text"),CIT=Set.of("documentVersionId","page","section","quote");private QuestionSetBusinessValidator(){}public static QuestionSetValidationResult validate(JsonNode root){List<ValidationProblem>p=new ArrayList<>();if(root==null||!root.isObject())return new QuestionSetValidationResult(false,List.of(new ValidationProblem("/","Bộ câu hỏi phải là JSON object")));unknown(root,ROOT,"/",p);if(!"1.0".equals(root.path("schemaVersion").asText()))p.add(new ValidationProblem("/schemaVersion","schemaVersion phải là 1.0"));JsonNode source=root.path("source");Set<String>docs=new HashSet<>();if(!source.isObject())p.add(new ValidationProblem("/source","Thiếu thông tin nguồn"));else{unknown(source,SOURCE,"/source",p);uuid(source.path("courseId").asText(),"/source/courseId",p);JsonNode d=source.path("documentVersionIds");if(!d.isArray()||d.isEmpty())p.add(new ValidationProblem("/source/documentVersionIds","Phải có ít nhất một phiên bản tài liệu nguồn"));else for(int i=0;i<d.size();i++){String v=d.get(i).asText();uuid(v,"/source/documentVersionIds/"+i,p);if(!docs.add(v))p.add(new ValidationProblem("/source/documentVersionIds/"+i,"documentVersionId bị trùng"));}}int ll=root.path("language").asText().length();if(ll<2||ll>16)p.add(new ValidationProblem("/language","Mã ngôn ngữ phải dài từ 2 đến 16 ký tự"));JsonNode qs=root.path("questions");if(!qs.isArray()||qs.isEmpty()){p.add(new ValidationProblem("/questions","Bộ câu hỏi phải có ít nhất một câu"));return new QuestionSetValidationResult(false,p);}if(qs.size()>500)p.add(new ValidationProblem("/questions","Bộ câu hỏi không được vượt quá 500 câu"));Set<String>external=new HashSet<>();for(int i=0;i<qs.size();i++){JsonNode q=qs.get(i);String b="/questions/"+i;if(!q.isObject()){p.add(new ValidationProblem(b,"Câu hỏi phải là JSON object"));continue;}unknown(q,QUESTION,b,p);String eid=q.path("externalId").asText().trim();if(eid.isEmpty()||eid.length()>100)p.add(new ValidationProblem(b+"/externalId","externalId không hợp lệ"));else if(!external.add(eid))p.add(new ValidationProblem(b+"/externalId","externalId bị trùng"));String type=q.path("type").asText();if(!TYPES.contains(type))p.add(new ValidationProblem(b+"/type","Loại câu hỏi không được hỗ trợ"));int sl=q.path("stem").asText().trim().length();if(sl<5||sl>4000)p.add(new ValidationProblem(b+"/stem","Nội dung câu hỏi phải dài từ 5 đến 4000 ký tự"));if(!DIFF.contains(q.path("difficulty").asText()))p.add(new ValidationProblem(b+"/difficulty","Độ khó phải là EASY, MEDIUM hoặc HARD"));if(!q.path("points").isNumber()||q.path("points").asDouble()<=0||q.path("points").asDouble()>1000)p.add(new ValidationProblem(b+"/points","Điểm phải lớn hơn 0 và không vượt quá 1000"));JsonNode options=q.path("options");Set<String>optionIds=new HashSet<>();if(!options.isArray()||options.size()<2||options.size()>10)p.add(new ValidationProblem(b+"/options","Câu hỏi phải có từ 2 đến 10 phương án"));else for(int j=0;j<options.size();j++){JsonNode o=options.get(j);unknown(o,OPT,b+"/options/"+j,p);String id=o.path("id").asText();if(!OPTION.matcher(id).matches())p.add(new ValidationProblem(b+"/options/"+j+"/id","Mã phương án không hợp lệ"));else if(!optionIds.add(id))p.add(new ValidationProblem(b+"/options/"+j+"/id","Mã phương án bị trùng"));if(o.path("text").asText().trim().isEmpty())p.add(new ValidationProblem(b+"/options/"+j+"/text","Nội dung phương án không được trống"));}Set<String>correct=new HashSet<>();JsonNode cn=q.path("correctOptionIds");if(cn.isArray())cn.forEach(x->correct.add(x.asText()));if(correct.isEmpty())p.add(new ValidationProblem(b+"/correctOptionIds","Phải có ít nhất một đáp án đúng"));if(!optionIds.containsAll(correct))p.add(new ValidationProblem(b+"/correctOptionIds","Đáp án đúng không tồn tại trong options"));if(Set.of("SINGLE_CHOICE","TRUE_FALSE").contains(type)&&correct.size()!=1)p.add(new ValidationProblem(b+"/correctOptionIds","Loại câu hỏi này phải có đúng một đáp án"));if("TRUE_FALSE".equals(type)&&options.isArray()&&options.size()!=2)p.add(new ValidationProblem(b+"/options","Câu đúng/sai phải có đúng hai phương án"));if(q.path("explanation").asText().trim().isEmpty())p.add(new ValidationProblem(b+"/explanation","Phải có giải thích đáp án"));JsonNode citations=q.path("citations");if(!citations.isArray()||citations.isEmpty())p.add(new ValidationProblem(b+"/citations","Phải có trích dẫn nguồn"));else for(int j=0;j<citations.size();j++){JsonNode c=citations.get(j);String cb=b+"/citations/"+j;unknown(c,CIT,cb,p);if(!docs.contains(c.path("documentVersionId").asText()))p.add(new ValidationProblem(cb+"/documentVersionId","Trích dẫn không thuộc tài liệu nguồn"));if(c.path("quote").asText().trim().isEmpty())p.add(new ValidationProblem(cb+"/quote","Trích dẫn phải có nội dung nguyên văn"));if(c.has("page")&&!c.path("page").isNull()&&c.path("page").asInt()<1)p.add(new ValidationProblem(cb+"/page","Số trang phải từ 1"));}}return new QuestionSetValidationResult(p.isEmpty(),p);}private static void unknown(JsonNode n,Set<String>a,String path,List<ValidationProblem>p){if(!n.isObject())return;n.fieldNames().forEachRemaining(f->{if(!a.contains(f))p.add(new ValidationProblem("/".equals(path)?"/"+f:path+"/"+f,"Trường không thuộc JSON Schema chung"));});}private static void uuid(String v,String path,List<ValidationProblem>p){try{UUID.fromString(v);}catch(Exception e){p.add(new ValidationProblem(path,"UUID không hợp lệ"));}}}
